	var one string
	if err := json.Unmarshal(data, &one); err == nil {
		*t = vueCorpusTypes{one}
		return nil
	}
	var many []string
	if err := json.Unmarshal(data, &many); err != nil {
		return fmt.Errorf("relation type must be a string or a list of strings: %w", err)
	}
	*t = many
	return nil
}

