	Line int    `json:"line"`
	Tag  string `json:"tag"`
}

type vueCorpusAbsent struct {
	File string `json:"file"`
	Name string `json:"name"`
	Kind string `json:"kind,omitempty"`
	Tag  string `json:"tag"`
	Why  string `json:"why"`
}

type vueCorpusRelation struct {
