func testRelations(stop func() bool, recordsByFile map[string][]SymbolRecord, symbolsByShortName map[string][]SymbolRecord, resolvedImportsByFile map[string]map[string][]string) []RelationRecord {
	paths := make([]string, 0, len(recordsByFile))
	for path := range recordsByFile {
		paths = append(paths, path)
	}
	sort.Strings(paths)

	var relations []RelationRecord
	for _, path := range paths {
		if stop != nil && stop() {
			return relations
		}
		for _, symbol := range recordsByFile[path] {
			if stop != nil && stop() {
				return relations
			}
			if symbol.Kind != "function" && symbol.Kind != "method" {
				continue
			}
			subject := testSubjectName(symbol.Name)
			if subject == "" {
				continue
			}
			target, resolution, ok := resolveTestSubject(stop, subject, symbol, symbolsByShortName[subject], resolvedImportsByFile[path])
			if !ok {
				continue
			}
			relations = append(relations, RelationRecord{
				RecordType:    "relation",
				FromID:        symbol.ID,
				ToID:          target.ID,
				Type:          "TESTS",
				Confidence:    0.8,
				Reason:        "test name maps to the unit under test by convention",
				RelationScope: "module",
				Resolution:    resolution,
				TargetKind:    "symbol",
				Evidence: []Evidence{{
					Kind:      "test_name",
					FilePath:  symbol.FilePath,
					StartLine: symbol.StartLine,
					EndLine:   symbol.EndLine,
					Detail:    subject,
				}},
				WarningCodes: []string{},
			})
		}
	}
	return relations
}

