	// states whether a dependents_count value is a heuristic estimate or one
	// degraded further by a scan limit. 1.4 added optional derived relation
	// provenance; 1.3 added source-file health accounting; 1.2 added
	// optional parser identity metadata.
	// Schema 1.1 added the snapshot fields introduced
	// alongside boundary source locations (the `external` flag on external records
	// and the per-symbol source-location fields). The shape is backward compatible
	// for tolerant readers; the bump lets consumers detect the new fields.
	SchemaVersion         = "1.6"
	ProviderName          = "entire-graph"
	StableSymbolIDVersion = "compound-v1"
	// IdentityRevision is a global, opaque revision of parser identity rules across
	// all languages. Change it when corrections re-key existing symbols.
	//
	// Revision 8: recover PostgreSQL identity columns, named CHECK constraints,
	// and DO blocks with LANGUAGE clauses while preserving static declarations.
	// Stop treating identifier prefixes as constraints. Invalidate cached partial
	// snapshots so previously excluded migrations are indexed for unchanged trees.
	//
	// Revision 7: repair Swift 0.7.4 conditional attributes, ownership switches,
	// multiline constraints, type-body and switch-prefix diagnostics, comment
	// lookahead, compilation conditions and directive-prefixed macros. Recovered
	// declarations and relations must invalidate snapshots built by the unpatched
	// grammar.
	//
	// Revision 6: Swift is parsed by the vendored tree-sitter-swift v0.7.4
	// grammar instead of go-tree-sitter's 0.5.0 one. Files that failed to parse
	// before (freestanding macros such as `#expect`, newer syntax) now yield
	// different declarations, and the caches are keyed on the source tree, so
	// revision-5 records must not be served for them.
	//
	// Revision 5: Julia declaration headers replace body-laden signatures.
	// Same-name overload IDs hash the signature, so their #sig: suffixes change
	// even for unchanged source. Consumers must refresh snapshots and recompute
	// persisted entity deltas under the corrected parser rules.
	//
	// Revision 4: the same correction for Swift, Kotlin, Rust and PHP, whose
	// nested callables are local functions / block-scoped items / namespace
	// functions rather than members of the enclosing type. Revision 3 shipped
	// the Python half; a build carrying only that half wrote records under the
	// revision-3 namespace, so these four need their own bump to stop those
	// records being served for the languages they do not cover.
	//
	// Revision 3: Python nested callables are qualified by the enclosing
	// CALLABLE rather than the enclosing class, so a helper defined inside a
	// method is `C.m.helper` (kind "function") instead of the phantom member
	// `C.helper` (kind "method"). This re-keys every Python nested-callable
	// symbol, and it un-keys the `#sig:` suffixes that the phantom forced onto
	// real same-named members.
	IdentityRevision     = "8"
	defaultMaxParseBytes = 4 * 1024 * 1024
	// defaultMaxSourceFiles bounds how many files one snapshot will list. The
	// per-file indexes a snapshot keeps (one file record and its retained symbols)
// the sidecar's digest. Entries written by earlier builds embed the records
// inline and are unreadable at this version (and vice versa).
// v21 retires streams carrying DATA_FLOWS edges matched by another language's
// expression patterns (a Python conditional pattern on a Go body and the
// like); language-routed flow extraction no longer produces them.
// v22 retires streams carrying kind=tool symbols (and their HANDLES_TOOL edges)
// fabricated from body text; tool boundaries now come from identifiers only.
// v23 follows v22 and retires entries written before a failed
// co-change history read was disclosed. Such an entry is keyed exactly as this
// build keys the same failure (the history-unavailable scope and no pairs; the
// reason is not, and need not be, in the key), so without the bump this build
// replays its summary, which lacks W_COCHANGE_HISTORY_UNAVAILABLE: the silent
// drop the warning exists to end.
// v24 retires body-laden Julia signatures and module DATA_FLOWS edges.
// v25 retires summaries that report valid Go the bundled grammar cannot fully
// parse as an E_PARSE_ERROR partial failure; this build reports it as a
// W_GO_GRAMMAR_GAP warning, and a replayed v24 summary would keep the failure.
const providerRecordsCacheVersion = "provider-records-v25-" + IdentityRevision

// cachedProviderRecords is the on-disk envelope for a cached record stream. The
// key alone is authoritative (sha256 over version+commit+tree+mode+profile+
// options+path-file contents), but we re-validate the discriminating fields on
// read as defense-in-depth against a stale or hand-edited cache file.
type cachedProviderRecords struct {
	CacheVersion string `json:"cache_version"`
	// SchemaVersion is the sem.SchemaVersion the stored record stream was
	// serialized under. It is the only thing in this envelope that distinguishes
	// two wire shapes; see validCachedProviderRecords. Entries written before this
	// field existed decode as "" and are correctly rejected as a different schema.
	SchemaVersion   string  `json:"schema_version"`
	ProviderVersion string  `json:"provider_version"`
// expression patterns; language-routed flow extraction no longer produces them.
// v27 retires entries carrying kind=tool symbols fabricated from body text (a
// duplicate definition of the handler's name); tool boundaries now come from
// identifiers only.
// v28 follows v27 and retires entries written before a failed
// co-change history read was disclosed. The query path never serves such an entry
// (its history refresh fails, which is a miss), but `graph store` and `graph
// context` read the persisted entry and its sqlite sidecar without building, so a
// pre-disclosure entry would hand them a header without
// W_COCHANGE_HISTORY_UNAVAILABLE. The sidecar sits beside the entry under this
// version's directory, so the bump orphans stale stores as well.
// v29 retires body-laden Julia signatures and module DATA_FLOWS edges.
// v30 retires headers that report valid Go the bundled grammar cannot fully
// parse as an E_PARSE_ERROR partial failure instead of a W_GO_GRAMMAR_GAP warning.
const searchSnapshotCacheVersion = "search-snapshot-v30-" + IdentityRevision

type cachedSymbolByteRange struct {
	Start int `json:"start"`
	End   int `json:"end"`
}

