func signatureTypeRelations(stop func() bool, recordsByFile map[string][]SymbolRecord, symbolsByFile, symbolsByShortName map[string][]SymbolRecord, resolvedImportsByFile map[string]map[string][]string, spec profileSpec) []RelationRecord {
	paths := make([]string, 0, len(recordsByFile))
	for path := range recordsByFile {
		paths = append(paths, path)
	}
	sort.Strings(paths)

	var relations []RelationRecord
	for _, path := range paths {
		if stop != nil && stop() {
			return relations
		}
		for _, symbol := range recordsByFile[path] {
			if stop != nil && stop() {
				return relations
			}
			if symbol.Kind != "function" && symbol.Kind != "method" || symbol.Signature == "" {
				continue
			}
			importsByName := resolvedImportsByFile[path]
			qualifiedImportsByName := qualifiedTypeImports(symbol.Signature, importsByName)
			refs := symbolTypeReferences(symbol)
			for _, relationType := range []string{"PARAM_TYPE", "RETURNS_TYPE"} {
				if !spec.emits(relationType) {
					continue
				}
				names := refs[relationType]
				sort.Strings(names)
				emitted := map[string]bool{}
				for _, name := range names {
					target, resolution, scope, confidence, ok := resolveTypeReference(name, symbol, symbolsByFile[path], symbolsByShortName, importsByName, qualifiedImportsByName)
					if !ok || emitted[target.ID] {
						continue
					}
					emitted[target.ID] = true
					relations = append(relations, RelationRecord{
						RecordType:    "relation",
						FromID:        symbol.ID,
						ToID:          target.ID,
						Type:          relationType,
						Confidence:    confidence,
						Reason:        signatureTypeReason(relationType),
						RelationScope: scope,
						Resolution:    resolution,
						TargetKind:    "symbol",
						Evidence: []Evidence{{
							Kind:      "signature",
							FilePath:  symbol.FilePath,
							StartLine: symbol.StartLine,
							EndLine:   symbol.EndLine,
							Detail:    name,
						}},
						WarningCodes: []string{},
					})
				}
			}
		}
func splitSignatureTypes(language, signature string) (string, string) {
	open := strings.Index(signature, "(")
	close := matchingParen(signature, open)
	if open < 0 || close < 0 {
		return "", ""
	}
	params := signature[open+1 : close]
	after := strings.TrimSpace(signature[close+1:])
	before := strings.TrimSpace(signature[:open])
	switch language {
	case "Go", "Rust":
		return params, after
	case "TypeScript", "JavaScript", "Kotlin", "PHP":
		// PHP return types share the `): Type` suffix syntax; the default
		// prefix-scan below would misread `function name(` signatures.
		if strings.HasPrefix(after, ":") {
			after = strings.TrimSpace(strings.TrimPrefix(after, ":"))
			// PHP nullable return hint (`: ?Foo`).
			after = strings.TrimPrefix(after, "?")
		} else {
			after = ""
		}
		return params, after
	default:
		fields := strings.Fields(before)
		if len(fields) >= 2 {
			return params, fields[len(fields)-2]
		}
		return params, ""

